// @generated 2026-10-27 隐藏窗口任务助手：计划任务跑 node 时**绝不出现黑窗**
// [why] 2026-10-27 用户反馈「委托/后台检查时偶尔闪 node 黑窗」。Task Scheduler 直接
//       启动控制台程序（node.exe）会先建一个 console 再附加，肉眼可见一闪；改成
//       wscript.exe 跑一个 WScript.Shell.Run(cmd, 0, False) 的 VBS（窗口样式 0 = SW_HIDE），
//       控制台从头到尾不创建 → 无痕。VBS 只写一次，任务 action 指向它。
// 归宿：reusable（dsh-mesh/scripts/lib/）
import { existsSync, mkdirSync, writeFileSync } from 'node:fs'
import { spawnSync } from 'node:child_process'
import { homedir } from 'node:os'
import { join } from 'node:path'

export function meshHome() {
  return process.env.DSH_MESH_HOME || join(homedir(), '.dsh-mesh')
}

export function hiddenVbsPath() {
  return join(meshHome(), 'run-hidden.vbs')
}

/** Write (or refresh) the hidden launcher. Idempotent. */
export function ensureHiddenLauncher() {
  const vbs = hiddenVbsPath()
  mkdirSync(meshHome(), { recursive: true })
  const body = [
    "' @generated by dsh-mesh scripts/lib/hidden-task.mjs — runs a console program with NO window",
    "' usage: wscript.exe //nologo run-hidden.vbs <exe> <arg1> <arg2> ...",
    'Option Explicit',
    'Dim args, cmd, i',
    'Set args = WScript.Arguments',
    'If args.Count < 1 Then WScript.Quit 2',
    'cmd = """" & args(0) & """"',
    'For i = 1 To args.Count - 1',
    '  cmd = cmd & " " & """" & args(i) & """"',
    'Next',
    "' 0 = SW_HIDE, False = do not wait",
    'CreateObject("WScript.Shell").Run cmd, 0, False',
    ''
  ].join('\r\n')
  writeFileSync(vbs, body, 'utf8')
  return vbs
}

/** Build the schtasks /TR value that runs `node <script> ...args` with no window. */
export function hiddenTaskCommand(nodeExe, scriptPath, scriptArgs = []) {
  const vbs = ensureHiddenLauncher()
  return ['wscript.exe', '//nologo', vbs, nodeExe, scriptPath, ...scriptArgs].map((part) => `"${part}"`).join(' ')
}

export function taskState(taskName) {
  const r = spawnSync('schtasks', ['/Query', '/TN', taskName, '/FO', 'LIST'], { encoding: 'utf8', windowsHide: true })
  if (r.status !== 0) return { installed: false }
  const text = r.stdout || ''
  const status = (text.match(/^(?:Status|状态):\s*(.+)$/m) || [])[1]?.trim() || ''
  return { installed: true, status }
}

/** Create/replace a MINUTE-interval task whose action is hidden via VBS. */
export function installHiddenTask({ taskName, nodeExe, scriptPath, scriptArgs = [], intervalMin = 5 }) {
  const command = hiddenTaskCommand(nodeExe, scriptPath, scriptArgs)
  const r = spawnSync(
    'schtasks',
    ['/Create', '/TN', taskName, '/SC', 'MINUTE', '/MO', String(intervalMin), '/TR', command, '/F', '/RL', 'LIMITED'],
    { encoding: 'utf8', windowsHide: true }
  )
  return { ok: r.status === 0, exit: r.status, out: `${r.stdout || ''}${r.stderr || ''}`.trim(), command }
}

export function uninstallTask(taskName) {
  const r = spawnSync('schtasks', ['/Delete', '/TN', taskName, '/F'], { encoding: 'utf8', windowsHide: true })
  return { ok: r.status === 0, exit: r.status, out: `${r.stdout || ''}${r.stderr || ''}`.trim() }
}
